import assert from 'node:assert/strict';
import {mkdir,writeFile,chmod} from 'node:fs/promises';
import {resolve} from 'node:path';
import {loadE2EEnvironment} from '../../e2e/environment.ts';
const root=resolve('/Users/dingshinn/.codex/worktrees/step-07-review-round9/rpg-maker-maker/.local/step07-review/config-controls-'+Date.now());await mkdir(root,{recursive:true});
const keys=['DATABASE_URL','API_HOST','API_PORT','WEB_PORT','NODE_ENV'];const original={...process.env};
const cases:any[]=[];const db='[REDACTED_DSN]';
function clean(){for(const key of keys)delete process.env[key]}
function run(label:string,fn:()=>void){clean();fn();cases.push({label,result:'PASS'});}
const missing=resolve(root,'absent.env');
run('missing file + explicit owned loopback configuration',()=>{Object.assign(process.env,{DATABASE_URL:db,API_PORT:'4395',WEB_PORT:'5295'});const c=loadE2EEnvironment(missing);assert.equal(c.DATABASE_URL,db);assert.equal(c.API_PORT,4395);assert.ok(Object.isFrozen(c))});
run('missing required DB rejects with no fallback',()=>{assert.throws(()=>loadE2EEnvironment(missing),/requires DATABASE_URL/);assert.equal(process.env.DATABASE_URL,undefined)});
const file=resolve(root,'own.env');await writeFile(file,`DATABASE_URL=${db}\nAPI_PORT=4395\nWEB_PORT=5295\n`,{mode:0o600,flag:'wx'});
run('real local file load',()=>{const c=loadE2EEnvironment(file);assert.equal(c.DATABASE_URL,db);assert.deepEqual([c.API_PORT,c.WEB_PORT],[4395,5295]);});
run('explicit process wins conflicting real file',()=>{Object.assign(process.env,{DATABASE_URL:db.replace('tileset_fixture','tileset_explicit'),API_PORT:'4394',WEB_PORT:'5294'});const c=loadE2EEnvironment(file);assert.equal(c.DATABASE_URL,db.replace('tileset_fixture','tileset_explicit'));assert.deepEqual([c.API_PORT,c.WEB_PORT],[4394,5294]);});
run('actual EISDIR rejected despite valid process DB',()=>{process.env.DATABASE_URL=db;assert.throws(()=>loadE2EEnvironment(root),(e:any)=>e.message==='Unable to read the optional local E2E environment file.'&&e.cause.code!=='ENOENT')});
const denied=resolve(root,'denied.env');await writeFile(denied,'DATABASE_URL=UNREADABLE_CANARY\n',{mode:0,flag:'wx'});
run('actual unreadable EACCES produces native ENOENT and helper accepts explicit env COUNTEREXAMPLE',()=>{process.env.DATABASE_URL=db;const c=loadE2EEnvironment(denied);assert.equal(c.DATABASE_URL,db)});await chmod(denied,0o600);
for(const [label,patch] of Object.entries({remote:{DATABASE_URL:db.replace('127.0.0.1','example.invalid')},otherProjectDatabase:{DATABASE_URL:db.replace('tileset_fixture','postgres')},schemaQuery:{DATABASE_URL:db+'?schema=other'},invalidPort:{API_PORT:'no'},samePorts:{API_PORT:'5295',WEB_PORT:'5295'},invalidHost:{API_HOST:'0.0.0.0'},invalidMode:{NODE_ENV:'other'},emptyDatabase:{DATABASE_URL:''}}))run(label,()=>{process.env.DATABASE_URL=db;Object.assign(process.env,patch);assert.throws(()=>loadE2EEnvironment(missing),(e:any)=>!e.message.includes('REVIEW_CANARY')&&!e.message.includes('postgresql://'))});
for(const key of keys){if(original[key]===undefined)delete process.env[key];else process.env[key]=original[key]}
console.log(JSON.stringify({cases,count:cases.length,network:'no network/client imports or instantiation; parse-only fixture'},null,2));
